package android.graphics;import android.hardware.HardwareBuffer;import java.util.*;import java.util.concurrent.*;
public class Bitmap{public enum Config{ARGB_8888}public static final List<Bitmap> all=new CopyOnWriteArrayList<>();public static volatile CountDownLatch copied=new CountDownLatch(1);public static volatile boolean failCopy;private final int w,h;public boolean recycled;public Bitmap(int w,int h){this.w=w;this.h=h;all.add(this);}public int getWidth(){return w;}public int getHeight(){return h;}public static Bitmap wrapHardwareBuffer(HardwareBuffer b,ColorSpace c){return new Bitmap(b.getWidth(),b.getHeight());}public Bitmap copy(Config c,boolean m){copied.countDown();if(failCopy)throw new IllegalStateException("copy failed");return new Bitmap(w,h);}public static Bitmap createBitmap(int w,int h,Config c){return new Bitmap(w,h);}public static Bitmap createScaledBitmap(Bitmap b,int w,int h,boolean f){return new Bitmap(w,h);}public void getPixels(int[] p,int o,int s,int x,int y,int w,int h){Arrays.fill(p,0xff778899);}public void recycle(){recycled=true;}public boolean isRecycled(){return recycled;}}
